                raise AcceptanceError("fresh virtual environment creation failed")

            env = os.environ.copy()
            for name in (
                "PIP_EXTRA_INDEX_URL",
                "PIP_FIND_LINKS",
                "PIP_INDEX_URL",
                "PIP_TRUSTED_HOST",
            ):
